# ---------------------------------------------------------------- SUJETS
# (id du sujet, numéro de la partie, arguments ajoutés)
# L'auteur n'est ajouté que là où son raisonnement apporte réellement un
# argument : chaque sujet est visé nommément, et l'argument est inséré à la fin
# de la partie du plan où il prend sa place dans la démonstration.
SUJETS = [
 # ---------------------------------------------------------- ch1
 ('ch1-5', 2, ["La courbe de Laffer fournit l'argument théorique de ce freinage : les recettes fiscales étant le produit d'un taux par une base imposable, un taux trop élevé peut contracter la base au point de réduire le produit de l'impôt. Le cours rappelle toutefois que cette courbe ne repose pas sur des faits empiriques solides et que les comportements s'ajustent lentement, souvent par l'optimisation plutôt que par le retrait de l'activité."]),
 ('ch1-20', 2, ["Au volet « crise de financement » identifié par Rosanvallon, la courbe de Laffer donne un contenu économique : le financement de la protection sociale finirait par détruire la base fiscale qui l'alimente. L'argument doit être immédiatement nuancé, les 483 niches fiscales françaises montrant que la base se déforme davantage qu'elle ne disparaît."]),
 # ---------------------------------------------------------- ch2
 ('ch2-5', 1, ["Irving Fisher donne à cette neutralité sa forme canonique avec l'équation des échanges MV = PT. L'identité n'est une théorie que sous deux hypothèses : la stabilité de la vitesse de circulation et la détermination réelle du volume des transactions. Contester l'une ou l'autre suffit à rouvrir la possibilité d'une monnaie agissant sur la production."]),
 ('ch2-5', 2, ["La courbe de Phillips, établie en 1958 sur le Royaume-Uni de 1861 à 1957, a semblé prouver que la monnaie n'était pas neutre : une inflation modérée pouvait réduire le chômage. La stagflation des années 1970 a montré que cette relation dépendait des anticipations, ce qui donne raison à Friedman sur le long terme sans rétablir la neutralité de court terme."]),
 ('ch2-12', 1, ["La remise en cause de la courbe de Phillips est le point de départ de cette critique : Friedman admet la relation à court terme par l'illusion monétaire, mais la rend verticale à long terme, le chômage revenant à son taux naturel. Il ne reste alors que l'inflation, d'où la conclusion d'une politique monétaire impuissante à agir sur l'emploi."]),
 ('ch2-4', 2, ["Le cas du Bitcoin, créé en 2008 sous le pseudonyme de Satoshi Nakamoto, est décisif : sa masse monétaire est plafonnée à 21 millions d'unités. Cette fixité, présentée comme une garantie contre l'inflation, est précisément ce qui interdit d'amortir les chocs de demande et explique une volatilité incompatible avec les fonctions d'unité de compte et de réserve de valeur."]),
 ('ch2-11', 1, ["Le Bitcoin de Satoshi Nakamoto remplace la confiance institutionnelle par une vérification décentralisée via la blockchain : la promesse est de se passer des banques et des États. Mais l'absence d'autorité capable d'ajuster la quantité de monnaie à l'activité, loin d'être un détail technique, est ce qui empêche la stabilité du pouvoir d'achat."]),
 ('ch2-8', 1, ["Pour Fisher comme pour Friedman, l'inflation est un phénomène monétaire : si la masse monétaire croît plus vite que la production, les prix augmentent mécaniquement. C'est le cadre à poser avant d'examiner les chocs d'offre, qui échappent à cette explication."]),
 # ---------------------------------------------------------- ch3
 ('ch3-1', 2, ["La théorie du déséquilibre (Clower, Leijonhufvud, Malinvaud) fournit l'argument le plus fort contre l'autorégulation : un agent rationné sur le marché du travail voit son revenu baisser, donc sa demande de biens se contracter, ce qui réduit la production et l'emploi. L'ajustement se fait par les quantités et l'économie peut se stabiliser dans un équilibre de sous-emploi, où aucun agent n'a individuellement intérêt à changer de comportement."]),
 ('ch3-2', 3, ["Malinvaud subordonne l'intervention à un diagnostic : la quantité échangée étant le minimum de l'offre et de la demande, le chômage est keynésien lorsque les débouchés manquent et classique lorsque la rentabilité est insuffisante. Une relance appliquée au second régime n'alimenterait que les prix, ce qui déplace le débat de l'opportunité de l'intervention vers son adéquation au régime constaté."]),
 ('ch3-11', 2, ["Hayek montre que le libéralisme n'est pas homogène : l'information étant dispersée, le marché n'est pas un état d'équilibre mais un processus de découverte, et c'est l'imperfection de l'information qui rend la concurrence utile. Il admet par ailleurs l'instabilité du capitalisme, une création monétaire excessive abaissant artificiellement les taux et provoquant un surinvestissement."]),
 ('ch3-14', 3, ["La Nouvelle Économie Keynésienne (Akerlof, Stiglitz, Mankiw) assure la pertinence actuelle du keynésianisme : elle accepte rationalité et microfondements, puis montre que les asymétries d'information et les coûts de modification des prix suffisent à produire du chômage involontaire. Le cours rappelle que la plupart des modèles utilisés aujourd'hui par les banques centrales sont d'inspiration nouvelle keynésienne."]),
 ('ch3-7', 2, ["Le désaccord porte souvent moins sur les faits que sur les hypothèses : la Nouvelle Économie Classique de Lucas et Sargent conclut de la rationalité des agents à l'inutilité de l'État, alors que la Nouvelle Économie Keynésienne accepte cette même rationalité et conclut l'inverse en y ajoutant l'imperfection de l'information."]),
 ('ch3-17', 2, ["Hayek, de l'intérieur de la tradition libérale, refuse l'équilibre général walrasien : l'information étant dispersée et subjective, la concurrence pure et parfaite décrit une situation où la concurrence n'aurait plus d'objet. Le reproche de l'irréalisme ne vient donc pas seulement des hétérodoxes."]),
 # ---------------------------------------------------------- ch4
 ('ch4-3', 2, ["Le théorème d'Arrow-Debreu rend la difficulté mesurable en explicitant sept conditions, dont la complétude des marchés futurs, une dotation initiale de survie et l'absence de coûts fixes. Deux d'entre elles se retournent contre la thèse qu'elles servent : la dotation de survie suppose une intervention extérieure au marché, et l'absence de coûts fixes contredit toute l'industrie réelle."]),
 ('ch4-13', 2, ["Le théorème de Sonnenschein, Mantel et Debreu établit que la fonction de demande agrégée peut prendre presque n'importe quelle forme : l'existence d'un équilibre n'implique ni sa stabilité ni la convergence du tâtonnement vers lui. La rationalité individuelle ne garantit donc pas la régularité de l'agrégat, et l'autorégulation apparaît comme un postulat du modèle plutôt que comme l'une de ses conclusions."]),
 ('ch4-20', 2, ["La critique la plus forte est interne : après Arrow et Debreu, qui démontrent l'existence de l'équilibre sous des hypothèses très restrictives, Sonnenschein et Mantel établissent qu'un équilibre existant peut être totalement instable. On obtient un équilibre théoriquement possible, pratiquement inaccessible et mathématiquement instable."]),
 # ---------------------------------------------------------- ch5
 ('ch5-9', 2, ["Tullock et l'école des choix publics donnent un contenu précis à la défaillance de l'État : lorsque la décision publique peut créer des avantages, des agents rationnels consacrent des ressources à les obtenir plutôt qu'à produire. Cette recherche de rente est privément rentable et socialement stérile, et l'asymétrie d'incitation favorise systématiquement les groupes concentrés contre les coûts diffus."]),
 ('ch5-7', 3, ["Établir une défaillance de marché ne suffit donc pas à justifier une intervention : il faut comparer l'imperfection du marché à celle de la procédure publique censée la corriger, ce que Tullock et Buchanan opposent frontalement à l'analyse pigouvienne."]),
 ('ch5-18', 1, ["La loi de Gresham, « la mauvaise monnaie chasse la bonne », fournit la formule générale de la sélection adverse : quand l'acheteur ne peut distinguer la qualité, le prix unique pénalise les bonnes unités et évince leurs détenteurs, la qualité moyenne de l'offre baissant de façon cumulative jusqu'à la disparition possible du marché."]),
 # ---------------------------------------------------------- ch6
 ('ch6-1', 2, ["Aghion et Howitt expliquent le rythme même du progrès technique, que Solow laissait inexpliqué : la croissance procède d'innovations successives qui rendent obsolètes les technologies antérieures, et son taux dépend de l'intensité de la R&D et du régime de concurrence. La croissance devient ainsi un résultat institutionnel autant que technique."]),
 ('ch6-3', 2, ["Chez Aghion et Howitt, l'innovation est verticale : elle améliore une technologie existante et dévalorise la précédente, ainsi que les investissements et les qualifications qui lui étaient attachés. La croissance a donc un coût et des perdants, et elle est maximale pour un degré intermédiaire de concurrence — assez pour aiguillonner, pas assez pour supprimer la rente qui finance la recherche."]),
 ('ch6-4', 1, ["Aghion soutient que le ralentissement observé est en partie un problème de mesure : les services numériques gratuits créent de l'utilité sans transaction monétaire, et les améliorations de qualité à prix constant sont mal enregistrées par les indices. La productivité réelle pourrait donc être sous-estimée, même si ces gains non mesurés n'expliquent pas toute l'ampleur du ralentissement."]),
 ('ch6-5', 1, ["Larry Summers réactive en 2013 le concept formulé par Hansen en 1938 : un excès durable de l'épargne désirée sur l'investissement désiré exigerait un taux d'intérêt d'équilibre très bas, que la politique monétaire ne peut atteindre. L'économie se stabilise alors en dessous de son potentiel, ce qui déplace la réponse attendue du terrain monétaire vers le terrain budgétaire."]),
 ('ch6-7', 1, ["La notion de capital humain, popularisée par Gary Becker dans les années 1960, désigne le stock de caractéristiques physiques et intellectuelles incorporées aux individus et valorisables sur le marché du travail. Elle transforme la formation en investissement — coût immédiat, rendement étalé sur la vie active — et c'est elle que Lucas mobilise en 1988 pour faire de l'accumulation de savoir le moteur endogène de la croissance."]),
 ('ch6-8', 2, ["Aghion tire de la destruction créatrice cinq fonctions publiques, dont celle d'amortisseur : le renouvellement productif engendre chômage, reconversions et chocs locaux, que l'État doit atténuer. Toute destruction n'est donc créatrice qu'à la condition d'un accompagnement qui n'est pas produit par le marché lui-même."]),
 ('ch6-9', 1, ["La courbe environnementale de Kuznets, transposée par Grossman et Krueger (Quarterly Journal of Economics, 1995), soutient la possibilité d'une croissance verte : la pollution croît d'abord avec le revenu, puis décroît sous l'effet de la tertiarisation, des technologies de dépollution et d'une demande sociale de régulation."]),
 ('ch6-9', 2, ["Cette thèse échoue cependant sur les pollutions globales : le profil en U inversé se vérifie pour les polluants locaux, dont les effets sont ressentis sur le territoire qui les produit, mais non pour les émissions de CO₂. Elle peut en outre masquer une simple externalisation géographique des nuisances, les pays riches ayant délocalisé leurs productions polluantes."]),
 ('ch6-11', 1, ["Le coefficient de Palma, proposé en 2011, rapporte la part du revenu détenue par les 10 % les plus riches à celle des 50 % les plus pauvres : plus sensible que le rapport interdécile aux transformations du sommet, il met en évidence une polarisation que le Gini construit sur la courbe de Lorenz peut laisser passer."]),
 ('ch6-12', 2, ["Les rendements décroissants imposés par la fonction de production Cobb-Douglas, retenue par Carré, Dubois et Malinvaud dans La croissance française (1972), contiennent déjà la conclusion : seul le terme technologique peut soutenir durablement le produit par tête. Mais ce terme est un résidu, déduit et non mesuré, qui recueille aussi l'organisation et les erreurs de mesure."]),
 ('ch6-15', 2, ["La transposition française du modèle, dans La croissance française de Carré, Dubois et Malinvaud (1972), en montre à la fois l'utilité et la limite : la décomposition attribue au résidu ce que le capital et le travail n'expliquent pas, et l'hypothèse de substituabilité des facteurs est contestable, une machine sans travail ne produisant rien."]),
 ('ch6-17', 2, ["L'indice de Theil permet de trancher : décomposable entre une composante inter-pays et une composante intra-pays, il montre que les deux évoluent en sens opposé depuis les années 1980, ce qu'un indicateur global laisse invisible."]),
 ('ch6-19', 2, ["Aghion fournit le critère de décision : la politique industrielle optimale dépend de la distance à la frontière technologique. Loin de celle-ci, la direction est connue et le ciblage sectoriel peu risqué ; à la frontière, nul ne sait quelle technologie l'emportera, et la diversité des tentatives devient la ressource principale, ce qui appelle concurrence, entrée et politique horizontale."]),
 ('ch6-20', 2, ["L'estimation de Frey et Osborne, environ 47 % des tâches automatisables, porte sur les tâches et non sur les emplois : l'automatisation retire d'un métier les opérations codifiables et laisse celles qui exigent jugement et relation. Les métiers sont donc recomposés plus souvent que supprimés, l'enjeu se déplaçant vers la nature des compétences et la transition professionnelle."]),
 # ---------------------------------------------------------- ch7
 ('ch7-2', 1, ["Le rapport Meadows, publié en 1972 pour le Club de Rome sous le titre The Limits to Growth, substitue aux limites économiques de la croissance des limites physiques : un prélèvement exponentiel sur des stocks finis conduit à un dépassement puis à un ajustement brutal. Sa critique porte sur l'hypothèse d'une technologie rigide."]),
 ('ch7-11', 2, ["L'identité de Kaya permet de mesurer la difficulté : les émissions se décomposent en population, PIB par habitant, intensité énergétique du PIB et intensité carbone de l'énergie. Les politiques climatiques n'agissent que sur les deux derniers termes, dont les progrès peuvent être intégralement annulés par la croissance des deux premiers — d'où la distinction entre efficacité et sobriété."]),
 ('ch7-10', 2, ["Mark Carney identifie en 2015 l'obstacle central avec la tragédie des horizons : les coûts de la transition sont immédiats et ses bénéfices futurs, alors que les acteurs sont évalués sur des horizons courts. Chacun a donc individuellement intérêt à différer, sans qu'aucun ne soit irrationnel, ce qui justifie l'intervention des régulateurs financiers."]),
 ('ch7-12', 2, ["Carney distingue trois risques que la transition fait peser sur l'économie : les risques physiques, les risques de responsabilité juridique et les risques de transition. Un actif peut perdre sa valeur sans être détruit, simplement parce qu'il devient risqué ou invendable, ce qui réduit aussi la capacité d'endettement de ses détenteurs."]),
 ('ch7-15', 1, ["Le modèle du vol d'oies sauvages d'Akamatsu (1937) montre que l'industrialisation peut être séquencée : importer, produire en substitution aux importations, exporter, puis céder les productions les plus simples aux pays plus tardifs. Protection initiale et ouverture ultérieure deviennent ainsi deux moments d'une même trajectoire, à condition que le leader monte continûment en gamme."]),
 ('ch7-15', 2, ["Le cycle de vie du produit de Raymond Vernon en fournit le mécanisme microéconomique : un bien conçu près des compétences techniques migre vers les pays à bas coûts une fois son procédé codifié, de sorte que les avantages comparatifs sont évolutifs et que le rattrapage par les suiveurs est structurellement possible."]),
 ('ch7-6', 2, ["Pierre Charbonnier rappelle que les impératifs économiques et écologiques entrent souvent en collision : l'ouverture commerciale recherche des coûts bas, la politique climatique impose des coûts supplémentaires, de sorte qu'une contrainte unilatérale déplace la production vers les territoires les moins régulés. L'ajustement carbone aux frontières cherche à neutraliser cet écart."]),
 ('ch7-7', 2, ["Guillaume Pitron montre que la transition substitue une dépendance à une autre : la Chine est le premier producteur de 33 des 51 ressources minérales indispensables, et la dépendance porte surtout sur l'étape de raffinage, plus difficile à contourner qu'une dépendance pétrolière."]),
 ('ch7-10', 3, ["Benjamin Lemoine montre dans Chasseurs d'États (2024) que la contrainte de financement s'exerce aussi par le droit : des fonds vautours rachètent à bas prix la dette d'États en difficulté puis en réclament le remboursement intégral devant les tribunaux, comme dans le cas argentin où 93 % des créanciers avaient accepté une restructuration."]),
 # ---------------------------------------------------------- ch8
 ('ch8-2', 2, ["Les grappes d'innovations alimentent surtout les cycles longs de type Kondratiev, d'une durée de cinquante à soixante ans, dont la phase descendante correspond à l'épuisement de la vague. Les cycles de Kitchin (trois à cinq ans, liés aux stocks) et de Juglar (huit à dix ans, liés à l'investissement et au crédit) rappellent que le capitalisme est traversé par plusieurs rythmes emboîtés : tout ralentissement n'est pas un épuisement de l'innovation."]),
 ('ch8-11', 2, ["Karl Polanyi fournit le fondement théorique du modèle des parties prenantes : dans La Grande Transformation (1944), il montre que l'économie est encastrée dans la société et que le marché ne peut en être le seul principe d'organisation. Sans cette analyse, l'approche des stakeholders se réduirait à une préférence morale."]),
 ('ch8-4', 2, ["Bruno Patino montre que le modèle des plateformes repose sur la captation de l'attention : leur revenu croît avec le temps d'écran et non avec la satisfaction procurée, de sorte que l'attention et les données en deviennent les intrants non rémunérés. Sherry Turkle en relève l'effet social avec la formule « seuls ensemble » : la connexion technique ne produit pas la sociabilité qu'elle semble multiplier."]),
 ('ch8-3', 2, ["Georges Friedmann montre, avec le « travail en miettes », que les limites sociales d'un modèle productif en sont aussi les limites économiques : la perte de sens engendre turn-over, absentéisme et malfaçons, dont les coûts annulent une partie des gains de spécialisation."]),
 # ---------------------------------------------------------- ch9
 ('ch9-14', 2, ["François et Lemercier refusent une vision linéaire du capitalisme : entreprises distribuées, organisées en réseaux contractuels de spécialistes, et entreprises intégrées, hiérarchisées et verticalement unifiées, coexistent durablement parce qu'elles répondent à des exigences différentes. La taille d'une firme ne mesure donc pas son degré de modernité."]),
 ('ch9-2', 1, ["Le cas de General Motors, construit par William Durant par rachat de Buick, Chevrolet et Cadillac, montre l'articulation entre mode de croissance et stratégie de marché : la croissance externe procure d'un coup les marques qui permettront ensuite une différenciation verticale par gammes."]),
 ('ch9-1', 1, ["Suzanne Berger rappelle qu'une première mondialisation s'est déployée entre 1870 et 1914, fondée sur la division internationale du travail. La mondialisation contemporaine repose au contraire sur la division internationale des processus productifs, ce qui oblige les entreprises à atteindre une taille internationale pour coordonner des chaînes fragmentées."]),
 # ---------------------------------------------------------- ch10
 ('ch10-6', 2, ["La loi de Brandolini (2013) explique ce paradoxe par une asymétrie de coûts : produire une affirmation fausse ne demande ni temps ni preuve, la réfuter exige sources, contexte et raisonnement. La capacité de réfutation étant bornée alors que le nombre d'émetteurs ne l'est pas, l'abondance d'informations ne produit pas mécaniquement plus de rationalité — ce que Bronner nomme la « démocratie des crédules »."]),
 # ---------------------------------------------------------- ch21
 ('ch21-7', 2, ["Bhagwati montre avec la croissance appauvrissante qu'une hausse de la production exportée peut détériorer suffisamment les termes de l'échange pour réduire le bien-être : lorsqu'un pays pèse lourd dans l'offre mondiale d'un produit à demande peu élastique, l'offre supplémentaire fait chuter le prix et la recette diminue malgré la hausse des volumes. Un pays peut donc être pénalisé par son propre succès productif."]),
 ('ch21-2', 2, ["Les séries de Maddison en donnent la mesure historique : l'écart de niveau de vie entre les pays les plus riches et les plus pauvres passe d'un rapport d'environ trois en 1820 à environ dix en 1913. La première mondialisation combine ainsi une convergence au sein de l'espace atlantique et une divergence avec les économies périphériques."]),
 ('ch21-14', 2, ["L'indice de Theil permet d'énoncer sans contradiction le résultat central : décomposable entre une composante inter-pays et une composante intra-pays, il montre que l'hypermondialisation réduit les écarts de niveau de vie moyen entre nations — le rapport entre niveaux de vie américain et chinois passe d'environ 24 en 1990 à environ 3,2 en 2024 — tout en accompagnant une réouverture des inégalités internes."]),
 ('ch21-17', 1, ["Dès 1791, Hamilton défend aux États-Unis un protectionnisme industriel qui protège les producteurs et finance simultanément l'industrialisation par les recettes douanières : l'avantage comparatif y est traité comme une construction, cinquante ans avant le protectionnisme éducateur de List."]),
 ('ch21-6', 2, ["Suzanne Berger tire de l'effondrement de la première mondialisation une leçon décisive : une intégration économique très avancée peut être remise en cause lorsque les tensions politiques deviennent dominantes. Les dépendances mutuelles, avantages en temps de paix, se convertissent en vulnérabilités dès que la logique de sécurité prend le pas sur celle de l'efficacité."]),
 ('ch21-9', 2, ["Les données de Maddison replacent ce déplacement dans la longue durée : les futurs BRIC représentaient environ 51 % du PIB mondial en 1700 et 55 % en 1820, avant que l'industrialisation occidentale ne fasse chuter leur poids. L'émergence actuelle peut donc s'interpréter comme un rééquilibrage historique plutôt que comme une nouveauté sans précédent."]),
 ('ch21-5', 2, ["Le modèle d'Akamatsu éclaire la logique de ces chaînes en Asie : la montée en gamme de l'économie la plus avancée libère des segments standardisés que les suiveurs reprennent, ce qui diffuse l'industrialisation tout en multipliant les échanges de biens intermédiaires — la diffusion du développement ayant pour contrepartie une interdépendance accrue autour du centre régional."]),
 ('ch21-20', 3, ["Le friendshoring, expression popularisée par Janet Yellen, montre comment les deux termes peuvent être conciliés sans fermeture : la production mondiale est maintenue mais sa géographie est redessinée selon les alliances. La stratégie suppose toutefois de pouvoir identifier durablement les partenaires fiables, alors que les investissements s'amortissent sur des décennies et que les alliances se recomposent."]),
 # ---------------------------------------------------------- ch22
 ('ch22-13', 2, ["Aghion fournit le principe directeur : l'État peut financer la recherche fondamentale et partager un risque qu'aucune entreprise ne capterait, tandis que la concurrence garantit la sélection et la diffusion des innovations. La répartition est fonctionnelle — l'État fait émerger, le marché trie et diffuse — ce qui écarte d'emblée les deux positions extrêmes."]),
 ('ch22-13', 3, ["Le trilemme d'Agarwal (2023) en rappelle le coût : champions nationaux, stabilité financière et budgétaire et forte croissance ne peuvent être maximisés ensemble. Soutenir massivement des champions suppose d'accepter une dégradation budgétaire — le « pari audacieux » plutôt américain —, préserver les finances publiques limite les moyens engagés, et renoncer au ciblage ramène à une politique horizontale moins coûteuse."]),
 ('ch22-14', 2, ["Aghion tranche ce débat par un critère : la politique industrielle optimale dépend de la distance à la frontière technologique. Loin de celle-ci, la direction est connue et le ciblage vertical peu risqué ; à la frontière, nul ne sait quelle technologie l'emportera, et la politique horizontale, la concurrence et l'entrée de nouvelles entreprises deviennent déterminantes."]),
 ('ch22-15', 2, ["Aghion et Élie Cohen précisent comment : l'approche top-down permet à l'État de sélectionner une priorité et de mobiliser des financements, l'approche bottom-up laisse aux acteurs de terrain le choix des solutions concrètes. L'État fixe la direction sans prétendre choisir la technologie — c'est le fonctionnement de la DARPA, dotée d'environ 4,3 milliards de dollars."]),
 ('ch22-17', 2, ["Sarah Guillou impose la distinction décisive : le protectionnisme vise à protéger les producteurs domestiques contre la concurrence étrangère, la souveraineté vise la maîtrise des dépendances critiques, ce qui peut se faire en restant ouvert. Depuis 2020, le basculement de l'efficience vers la résilience n'équivaut donc pas à une fermeture."]),
 ('ch22-17', 3, ["Combe et Guillou écartent la fausse solution avec le « mythe du potager » : un choc domestique — catastrophe naturelle, grève, crise énergétique — peut aussi interrompre une production entièrement localisée. C'est la concentration des sources, et non leur extranéité, qui crée la vulnérabilité, de sorte que la diversification géographique offre souvent plus de résilience que la relocalisation intégrale."]),
 ('ch22-4', 1, ["La crainte n'est pas nouvelle : le rapport Arthuis de 1993 annonçait entre trois et cinq millions d'emplois industriels français menacés, et Ross Perot avait dénoncé en 1992 un « giant sucking sound » par lequel l'ALENA aspirerait les emplois américains vers le Mexique."]),
 ('ch22-4', 2, ["Les travaux empiriques ont montré une ampleur bien plus limitée : le coût du travail n'est qu'une composante du coût total, et Krugman soutient dès le milieu des années 1990 que le progrès technique explique l'essentiel de la transformation de l'emploi industriel. Un différentiel de coût ne suffit donc pas à prédire un déplacement de production."]),
 ('ch22-5', 2, ["Le raisonnement de Grossman et Krueger nuance fortement l'accusation : les normes environnementales élevées apparaissent généralement avec le développement, de sorte qu'une réglementation plus faible dans un pays émergent ne traduit pas nécessairement une stratégie délibérée. Les pays riches eux-mêmes n'ont adopté des politiques ambitieuses que tardivement — le marché européen du carbone date de 2005."]),
 ('ch22-19', 2, ["Nicholas Mulder situe ces interventions dans l'histoire longue en distinguant quatre vagues de nationalisation : sauvetage bancaire dans les années 1930, reconstruction après 1945, souveraineté sur les ressources dans les années 1970, et depuis 2020 une logique de sécurité d'approvisionnement qui ne vise pas à étatiser l'économie mais à maîtriser des dépendances critiques."]),
 ('ch22-11', 2, ["L'Inflation Reduction Act illustre une réaction en chaîne : lorsqu'une grande puissance subventionne fortement son industrie, ses partenaires sont incités à l'imiter, de sorte que chacun dépense davantage pour un avantage net faible. A. Bouët rappelle toutefois que l'Europe conserve des atouts propres et que l'ampleur du déplacement des investissements reste incertaine."]),
]

